text:
Componente listo para Next.js App Router, TypeScript, Tailwind v4 y GSAP. Usa `@gsap/react`, limpia correctamente la animación y respeta `prefers-reduced-motion`.

```tsx
// components/Hero.tsx
"use client";

import Link from "next/link";
import { useRef } from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";

gsap.registerPlugin(useGSAP);

type HeroProps = {
  eyebrow?: string;
  title?: string;
  subtitle?: string;
  primaryLabel?: string;
  primaryHref?: string;
  secondaryLabel?: string;
  secondaryHref?: string;
};

export function Hero({
  eyebrow = "Una nueva forma de avanzar",
  title = "Convierte buenas ideas en experiencias memorables.",
  subtitle = "Diseñamos productos digitales claros, rápidos y cuidadosamente construidos para impulsar tu próxima etapa.",
  primaryLabel = "Empezar un proyecto",
  primaryHref = "#contacto",
  secondaryLabel = "Ver nuestro trabajo",
  secondaryHref = "#proyectos",
}: HeroProps) {
  const containerRef = useRef<HTMLElement>(null);
  const titleRef = useRef<HTMLHeadingElement>(null);
  const subtitleRef = useRef<HTMLParagraphElement>(null);

  useGSAP(
    () => {
      const media = gsap.matchMedia();

      media.add("(prefers-reduced-motion: no-preference)", () => {
        gsap.to([titleRef.current, subtitleRef.current], {
          autoAlpha: 1,
          y: 0,
          duration: 0.9,
          stagger: 0.14,
          ease: "power3.out",
          clearProps: "transform",
        });
      });

      return () => media.revert();
    },
    { scope: containerRef },
  );

  return (
    <section
      ref={containerRef}
      className="relative isolate flex min-h-svh items-center overflow-hidden bg-[#f2efe8] px-6 py-24 text-[#171714] sm:px-10 lg:px-16"
    >
      <div
        aria-hidden="true"
        className="absolute -right-32 top-12 size-[32rem] rounded-full bg-[#d9ff5b]/55 blur-3xl"
      />

      <div
        aria-hidden="true"
        className="absolute bottom-[-12rem] left-[-8rem] size-[28rem] rounded-full border border-black/10"
      />

      <div className="relative mx-auto w-full max-w-7xl">
        <div className="max-w-5xl">
          <p className="mb-7 flex items-center gap-3 text-xs font-semibold uppercase tracking-[0.22em] text-black/55">
            <span className="size-2 rounded-full bg-[#9bc400]" />
            {eyebrow}
          </p>

          <h1
            ref={titleRef}
            className="max-w-5xl text-balance font-serif text-[clamp(3.5rem,9vw,8.5rem)] leading-[0.88] tracking-[-0.055em] motion-safe:translate-y-5 motion-safe:opacity-0"
          >
            {title}
          </h1>

          <p
            ref={subtitleRef}
            className="mt-8 max-w-2xl text-pretty text-lg leading-relaxed text-black/60 motion-safe:translate-y-5 motion-safe:opacity-0 sm:text-xl"
          >
            {subtitle}
          </p>

          <div className="mt-10 flex flex-col gap-3 sm:flex-row">
            <Link
              href={primaryHref}
              className="inline-flex min-h-12 items-center justify-center rounded-full bg-[#171714] px-7 text-sm font-semibold text-white transition-transform duration-300 hover:-translate-y-0.5 focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-black"
            >
              {primaryLabel}
            </Link>

            <Link
              href={secondaryHref}
              className="inline-flex min-h-12 items-center justify-center rounded-full border border-black/15 px-7 text-sm font-semibold transition-colors duration-300 hover:bg-black/5 focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-black"
            >
              {secondaryLabel}
              <span aria-hidden="true" className="ml-2">
                ↗
              </span>
            </Link>
          </div>
        </div>
      </div>
    </section>
  );
}
```

Uso:

```tsx
import { Hero } from "@/components/Hero";

export default function Page() {
  return (
    <main>
      <Hero />
    </main>
  );
}
```

El título entra primero y el subtítulo `140 ms` después, ambos con fade y un desplazamiento vertical de `20 px`. Para usuarios con movimiento reducido, el contenido se muestra directamente.
